func createBenchmark(policyBytes []byte) func() {
	mspMgr := createMSPManager()

	provider := cauthdsl.NewPolicyProvider(mspMgr)
	_ = provider

	pol, _, err := provider.NewPolicy(policyBytes)
	if err != nil {
		panic(err)
	}

	endorser := createEndorserSigner()
	msgToSign := make([]byte, 700)
	_, err = rand.Read(msgToSign)
	if err != nil {
		panic(err)
	}

	sig, err := endorser.Sign(msgToSign)
	if err != nil {
		panic(err)
	}

	benchmarkFunc := func() {
		err = pol.EvaluateSignedData([]*protoutil.SignedData{
			{
				Identity:  endorser.Creator,
				Data:      msgToSign,
				Signature: sig,
			},
		})
		if err != nil {
			panic(err)
		}
	}

	// Warmup cache
	benchmarkFunc()

	return benchmarkFunc
}

func benchAmortize(iterations int, benchFunc func() int) int {
	var total int
	for i := 0; i < iterations; i++ {
		total += benchFunc()
		time.Sleep(time.Second)
	}
	return total / iterations
}

func benchmark(f func()) int {
	start := make(chan struct{})
	var stop uint32
	var total uint32
	var startWG sync.WaitGroup
	startWG.Add(runtime.NumCPU())
	var stopWG sync.WaitGroup
	stopWG.Add(runtime.NumCPU())
	for p := 0; p < runtime.NumCPU(); p++ {
		go func() {
			defer stopWG.Done()
			// Signal we started
			startWG.Done()
			// Wait for everyone else to start
			<-start

			var count uint32
			// Until we are signaled to stop,
			for atomic.LoadUint32(&stop) != 1 {
				// Perform 1000 iterations of the function
				for i := 0; i < 1000; i++ {
					f()
				}
				count += 1000
			}
			// Once we are signaled to stop, add the number of operations
			// we did to the total count atomically
			atomic.AddUint32(&total, count)
		}()
	}

	startWG.Wait()
	time.Sleep(time.Millisecond * 500)
	// Signal all workers to start
	close(start)
	// Give them 10 seconds to work
	time.Sleep(time.Second * 10)
	// Signal them all to stop
	atomic.StoreUint32(&stop, 1)
	// Wait for them all to stop
	stopWG.Wait()
	// Measure throughput
	throughput := atomic.LoadUint32(&total) / 10
	return int(throughput)
}

func main() {
	fmt.Println(runtime.NumCPU(), "CPUs detected")
	fmt.Println("Policy size | Throughput")
	fmt.Println("-------------------------")

	for policySize := 4; policySize < 1025; policySize *= 2 {
		thresholdPolicy := protoutil.MarshalOrPanic(identityBasedEndorsementPolicy(policySize))
		benchmarkThresholdPolicy := createBenchmark(thresholdPolicy)
		amortizedThroughput := benchAmortize(10, func() int {
			return benchmark(benchmarkThresholdPolicy)
		})

		fmt.Printf("   %s     |     %d    \n", formatDecimal(policySize), amortizedThroughput)
	}

}

type signer struct {
	key     *ecdsa.PrivateKey
	Creator []byte
}

func newSigner() (*signer, error) {
	key, err := loadPrivateKey()
	if err != nil {
		return nil, errors.WithStack(err)
	}
	return &signer{
		Creator: decodeOrPanic(``),
		key:     key,
	}, nil
}

func (si *signer) Sign(msg []byte) ([]byte, error) {
	digest := util.ComputeSHA256(msg)
	return signECDSA(si.key, digest)
}

func loadPrivateKey() (*ecdsa.PrivateKey, error) {
	bl, _ := pem.Decode(decodeOrPanic(``))
	key, err := x509.ParsePKCS8PrivateKey(bl.Bytes)
	if err != nil {
		return nil, errors.WithStack(err)
	}
	return key.(*ecdsa.PrivateKey), nil
}

func signECDSA(k *ecdsa.PrivateKey, digest []byte) (signature []byte, err error) {
	r, s, err := ecdsa.Sign(rand.Reader, k, digest)
	if err != nil {
		return nil, err
	}

	s, err = bccsp.ToLowS(&k.PublicKey, s)
	if err != nil {
		return nil, err
	}
	return bccsp.MarshalECDSASignature(r, s)
}

func createMSPManager() msp.MSPManager {
	var mspsOfChannel []msp.MSP
	for _, mspConf := range []struct {
		mspID  string
		mspContent []byte
	}{
		{
			mspID:  "Org1MSP",
			mspContent: decodeOrPanic(Org1MSPConfig),
		},
		{
			mspID:  "Org2MSP",
			mspContent: decodeOrPanic(Org2MSPConfig),
		},
		{
			mspID:  "OrdererMSP",
			mspContent: decodeOrPanic(OrdererMSP),
		},
	} {
		mspInstance := createMSP(mspConf.mspContent)
		mspsOfChannel = append(mspsOfChannel, mspInstance)
	}

	mspMgr := msp.NewMSPManager()
	mspMgr.Setup(mspsOfChannel)
	return mspMgr
}

func createMSP(rawMspConf []byte) msp.MSP {
	cryptoProvider, err := sw.NewDefaultSecurityLevelWithKeystore(sw.NewDummyKeyStore())
	if err != nil {
		panic(err)
	}

	channelMSP, err := msp.New(
		&msp.BCCSPNewOpts{NewBaseOpts: msp.NewBaseOpts{Version: msp.MSPv1_4_3}},
		cryptoProvider,
	)
	if err != nil {
		panic(err)
	}

	// Surround it with a cache layer
	channelMSP, err = cache.New(channelMSP)

	mspConf := &msprotos.MSPConfig{}
	err = proto.Unmarshal(rawMspConf, mspConf)
	if err != nil {
		panic(err)
	}

	channelMSP.Setup(mspConf)
	return channelMSP
}

func createEndorserSigner() *signer {
	signer, err := newSigner()
	if err != nil {
		panic(err)
	}
	return signer
}

func identityBasedEndorsementPolicy(policySize int) *common.SignaturePolicyEnvelope {
	// Grab a peer certificate and add it into identityBasedPrincipals
	//identity := peerIdentity(peerDirPrefix, "Org1MSP", 1, 0)
	identity := decodeOrPanic(``)

	identityBasedPrincipals := [][]byte{
		identity,
	}
	rule := &common.SignaturePolicy{
		Type: &common.SignaturePolicy_NOutOf_{
			NOutOf: &common.SignaturePolicy_NOutOf{
				N:     1,
				Rules: []*common.SignaturePolicy{},
			},
		},
	}

	// Expand the principals with random identities that no one can satisfy and add them into identityBasedPrincipals
	for i := 0; i < policySize-1; i++ {
		buff := make([]byte, 700)
		_, err := rand.Read(buff)
		if err != nil {
			panic(err)
		}

		identityBasedPrincipals = append(identityBasedPrincipals, protoutil.MarshalOrPanic(&msprotos.SerializedIdentity{
			Mspid:   "Org1MSP",
			IdBytes: buff}))
	}

	// Permute the order between the principals
	var permutedIdentityBasedPrincipals [][]byte
	for _, index := range mathrand.Perm(len(identityBasedPrincipals)) {
		permutedIdentityBasedPrincipals = append(permutedIdentityBasedPrincipals, identityBasedPrincipals[index])
	}

	// Build the principals used for our policy
	var principals []*msprotos.MSPPrincipal
	for i, principal := range permutedIdentityBasedPrincipals {
		principals = append(principals, &msprotos.MSPPrincipal{
			Principal:               principal,
			PrincipalClassification: msprotos.MSPPrincipal_IDENTITY,
		})

		rule.GetNOutOf().Rules = append(rule.GetNOutOf().Rules, &common.SignaturePolicy{
			Type: &common.SignaturePolicy_SignedBy{
				SignedBy: int32(i),
			},
		})
	}

	return &common.SignaturePolicyEnvelope{
		Rule:       rule,
		Identities: principals,
	}
}

func formatDecimal(n int) string {
	s := bytes.Buffer{}

	if n < 999 {
		s.Write([]byte(" "))
	} else {
		s.WriteString(fmt.Sprintf("%d", n/1000))
	}

	if n < 99 {
		s.Write([]byte(" "))
	} else {
		s.WriteString(fmt.Sprintf("%d", (n%1000)/100))
	}

	if n < 10 {
		s.Write([]byte(" "))
	} else {
		s.WriteString(fmt.Sprintf("%d", (n%100)/10))
	}

	s.WriteString(fmt.Sprintf("%d", n%10))

	return s.String()
}

func decodeOrPanic(in string) []byte {
	b, err := base64.StdEncoding.DecodeString(in)
	if err != nil {
		panic(err)
	}
	return b
}

